// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SupportIssue) predicate.SupportIssue {
	return predicate.SupportIssue(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SupportIssue) predicate.SupportIssue {
	return predicate.SupportIssue(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SupportIssue) predicate.SupportIssue {
	return predicate.SupportIssue(sql.NotPredicates(p))
}
